@spec vm_temper_entry_spec  src=tests/specs/vm_temper_entry_spec.lua  loc=472  cases=17
@exercises tuning (tuning), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr)
@surface   tuning.derive, vm:setGridSize, tuning.midiToStep, ec:setPos, vm:editEvent, vm:digitsStrike, ec:pos, ec:row, vm:digitsBackspace, vm:digitsCommit, vm:digitsActive, vm:entrySignAt, vm:noteDeviation, cmgr:invoke, vm:noteLabel
@harness   mk{seed.notes}

# Intent
  Wired entry under a temperament: drives the real tv:editEvent path
  (not a re-implementation) so the pitch/octave snapping it performs is
  the production wiring. The octave column edits the temper's period-
  cycle octave, keeping the scale step, and rejects octaves a note
  cannot sit on exactly. See docs/tuning.md for the coordinate model.
  
  The same gestures settle what becomes of the intent a solve stamps on a
  note. A typed note and a transpose spend it, seating the note where it
  arrives; a move of whole 2/1 octaves carries it, drift and all
  (design/sounding-anchor.md § What the note remembers).

# Helpers
  @fn mk(harness, temper, notes)  @ 42-53
  @fn lane1(h)  @ 55-59
  @fn colIndex(h)  @ 61-64
  @fn stamped(pitch, detune, intentCents)  @ 67-70
      -- A note as a solve leaves one: where it sounds, and the step it was written on.
  @fn pitchStops(col)  @ 74-81
      -- The pitch part spans two cursor stops (note letter, octave digit);
      -- discover them so the test is independent of cellWidth.
  @fn octaveShown(h, temper)  @ 84-88
      -- The octave the cell shows: the period-index octave plus the octaveStep bump.
  @fn typeOctave(h, colIdx, char)  @ 91-96
      -- Types a char into the last place of the octave field, on the seeded note's row.
  @fn rootedNote(harness)  @ 99-113
      -- Places a note at the cursor and returns a typist for its octave stop.
  @fn narrowNote(harness)  @ 117-127
      -- Places a note under NARROW and returns the harness, its column index and the
      -- pitch part's three stops: the note name, then the octave's tens and units.

# Cases
  @case 'a shift-held digit walks the places of a two-char octave field'  [harness]  @ 131-152
  @case 'the octave gesture declines on the note-name stop'  [harness]  @ 156-162
  @case 'the octave gesture declines on a cell with no note'  [harness]  @ 166-172
  @case 'a plain digit on the tens place zeroes the units below it'  [harness]  @ 176-183
  @case 'the octave column negates in place, and the next digit keeps the sign'  [harness]  @ 187-208
  @case 'minus on octave zero arms the sign before the digit lands'  [harness]  @ 212-232
  @case 'a negated octave the note cannot sit on is a no-op'  [harness]  @ 236-247
  @case 'octave column keeps the scale step and sets the period-cycle octave'  [harness]  @ 251-279
  @case 'octave column rejects an octave the note cannot sit on exactly'  [harness]  @ 283-305
  @case 'typing a note over one a solve stamped clears the intent'  [harness]  @ 309-322
  @case 'a fine pitch nudge steps from the written step and spends the intent'  [harness]  @ 326-341
  @case 'a coarse pitch nudge carries the intent and the drift up the octave'  [harness]  @ 345-358
  @case 'the octave digit reads the step the note was written on'  [harness]  @ 362-380
  @case 'an octave digit that moves a whole 2/1 carries the intent, and any other spends it'  [harness]  @ 384-402
  @case 'the gesture's backspace restores an intent its octave digit spent'  [harness]  @ 406-421
  @case 'a coarse pitch nudge moves by one period of the temper'  [harness]  @ 425-439
  @case 'pitch nudge keeps a note in the addressable range (refuses past the ceiling)'  [harness]  @ 443-470

